/* Verification harness for lib/admin-audit.ts against the local Postgres.
   Creates rows under actorIds prefixed "audit-verify-", asserts, then deletes
   every row it created. */
const A = require("./build/admin-audit.js");
const { db } = require("./build/db.js");

const PREFIX = "audit-verify-";
const ACTOR_A = { id: PREFIX + "a", email: "verify-a@example.test" };
const ACTOR_B = { id: PREFIX + "b", email: "verify-b@example.test" };

let failures = 0;
function ok(name, cond, extra) {
  if (cond) console.log("  PASS  " + name);
  else {
    failures++;
    console.log("  FAIL  " + name + (extra === undefined ? "" : "  → " + JSON.stringify(extra)));
  }
}

const T0 = new Date("2020-01-01T00:00:00.000Z").getTime();
const at = (i) => new Date(T0 + i * 60_000);

async function main() {
  console.log("DATABASE_URL host:", (process.env.DATABASE_URL || "").replace(/\/\/.*@/, "//***@"));
  await db.$queryRaw`SELECT 1`;
  console.log("connected\n");

  // Start clean in case an earlier run died mid-way.
  await db.adminAuditLog.deleteMany({ where: { actorId: { startsWith: PREFIX } } });

  const beforeTotal = await db.adminAuditLog.count();
  const beforeCounts = await A.countAdminActions();
  const beforeActors = await A.listAdminActors();

  // ── 1. recordAdminAction writes a real row ─────────────────────────────
  await A.recordAdminAction(ACTOR_A, A.ADMIN_ACTIONS.userViewed, {
    targetType: A.ADMIN_TARGET_TYPES.user,
    targetId: "cust_1",
    meta: { via: "list", position: 3, filtered: true, dropped: undefined, nulled: null },
  });
  const written = await db.adminAuditLog.findFirst({
    where: { actorId: ACTOR_A.id },
    orderBy: { createdAt: "desc" },
  });
  ok("recordAdminAction inserted a row", !!written);
  ok("action stored verbatim", written.action === "user.viewed", written.action);
  ok("actorEmail denormalised", written.actorEmail === ACTOR_A.email);
  ok("target columns set", written.targetType === "user" && written.targetId === "cust_1");
  ok(
    "meta round-trips flat, undefined dropped, null kept",
    written.meta.via === "list" &&
      written.meta.position === 3 &&
      written.meta.filtered === true &&
      written.meta.nulled === null &&
      !("dropped" in written.meta),
    written.meta,
  );

  // ── 2. adminActionRow inside a $transaction ────────────────────────────
  await db.$transaction([
    db.adminAuditLog.create({
      data: {
        ...A.adminActionRow(ACTOR_A, A.ADMIN_ACTIONS.siteTakenDown, {
          targetType: A.ADMIN_TARGET_TYPES.project,
          targetId: "proj_9",
          meta: { reason: "phishing" },
        }),
        createdAt: at(1),
      },
    }),
  ]);
  ok(
    "adminActionRow row committed in a transaction",
    (await db.adminAuditLog.count({ where: { action: "site.taken_down", actorId: ACTOR_A.id } })) === 1,
  );

  // ── 3. A deterministic fixture for ordering / paging / filtering ───────
  // 7 more rows at known, distinct timestamps.
  const fixture = [
    [ACTOR_A, "user.viewed", at(10)],
    [ACTOR_B, "user.viewed", at(11)],
    [ACTOR_A, "flag.changed", at(12)],
    [ACTOR_B, "flag.changed", at(13)],
    [ACTOR_A, "user.viewed", at(14)],
    [ACTOR_B, "dashboard.viewed", at(15)],
    [ACTOR_A, "dashboard.viewed", at(16)],
  ];
  for (const [actor, action, createdAt] of fixture) {
    await db.adminAuditLog.create({
      data: { ...A.adminActionRow(actor, action, {}), createdAt },
    });
  }
  // An actor who changed email address, to exercise the dedupe in listAdminActors.
  await db.adminAuditLog.create({
    data: {
      ...A.adminActionRow({ id: ACTOR_A.id, email: "verify-a-old@example.test" }, "audit_log.viewed", {}),
      createdAt: at(-100),
    },
  });

  const mine = 1 + 1 + fixture.length + 1; // 10
  ok(
    "row count grew by exactly what we wrote",
    (await db.adminAuditLog.count()) === beforeTotal + mine,
    { beforeTotal, now: await db.adminAuditLog.count(), mine },
  );

  // ── 4. listAdminActions: ordering + totals ─────────────────────────────
  const all = await A.listAdminActions({ actorId: ACTOR_A.id, take: 100 });
  ok("filtered total matches", all.total === 6, all.total);
  ok("returns only that actor", all.entries.every((e) => e.actorId === ACTOR_A.id));
  const ts = all.entries.map((e) => e.createdAt.getTime());
  ok(
    "newest first",
    ts.every((t, i) => i === 0 || ts[i - 1] >= t),
    ts,
  );
  ok(
    "selects exactly the page's columns",
    Object.keys(all.entries[0]).sort().join(",") ===
      "action,actorEmail,actorId,createdAt,id,meta,targetId,targetType",
    Object.keys(all.entries[0]),
  );

  // ── 5. Filters actually filter ─────────────────────────────────────────
  const byAction = await A.listAdminActions({ action: "user.viewed", take: 100 });
  ok(
    "action filter returns only that action",
    byAction.entries.every((e) => e.action === "user.viewed") && byAction.total >= 3,
    { total: byAction.total },
  );
  const both = await A.listAdminActions({ actorId: ACTOR_B.id, action: "user.viewed", take: 100 });
  ok(
    "both filters compose (AND, not OR)",
    both.total === 1 && both.entries[0].actorId === ACTOR_B.id && both.entries[0].action === "user.viewed",
    { total: both.total },
  );
  const none = await A.listAdminActions({ actorId: PREFIX + "nobody", take: 100 });
  ok("unknown actor filters to zero, does not throw", none.total === 0 && none.entries.length === 0);

  // ── 6. Pagination ──────────────────────────────────────────────────────
  const p1 = await A.listAdminActions({ actorId: ACTOR_A.id, skip: 0, take: 2 });
  const p2 = await A.listAdminActions({ actorId: ACTOR_A.id, skip: 2, take: 2 });
  const p3 = await A.listAdminActions({ actorId: ACTOR_A.id, skip: 4, take: 2 });
  const p4 = await A.listAdminActions({ actorId: ACTOR_A.id, skip: 6, take: 2 });
  const paged = [...p1.entries, ...p2.entries, ...p3.entries].map((e) => e.id);
  ok("each page holds `take` rows", p1.entries.length === 2 && p2.entries.length === 2 && p3.entries.length === 2);
  ok("total is stable across pages", p1.total === 6 && p3.total === 6);
  ok("pages are disjoint and complete", new Set(paged).size === 6);
  ok(
    "paging order equals unpaged order",
    paged.join(",") === all.entries.map((e) => e.id).join(","),
  );
  ok("page past the end is empty, not an error", p4.entries.length === 0 && p4.total === 6);
  // What the page does with ?page=100000 after clamping.
  const far = await A.listAdminActions({ actorId: ACTOR_A.id, skip: (100_000 - 1) * 50, take: 50 });
  ok("clamped max page still queries cleanly", far.entries.length === 0 && far.total === 6);

  // ── 7. countAdminActions ───────────────────────────────────────────────
  const counts = await A.countAdminActions();
  ok(
    "counts grew per action by what we wrote",
    (counts.get("user.viewed") ?? 0) - (beforeCounts.get("user.viewed") ?? 0) === 4 &&
      (counts.get("flag.changed") ?? 0) - (beforeCounts.get("flag.changed") ?? 0) === 2 &&
      (counts.get("site.taken_down") ?? 0) - (beforeCounts.get("site.taken_down") ?? 0) === 1,
    { user: counts.get("user.viewed"), flag: counts.get("flag.changed") },
  );

  // ── 8. listAdminActors ─────────────────────────────────────────────────
  const actors = await A.listAdminActors();
  const a = actors.filter((x) => x.actorId === ACTOR_A.id);
  const b = actors.filter((x) => x.actorId === ACTOR_B.id);
  ok("each actor appears exactly once", a.length === 1 && b.length === 1, actors.map((x) => x.actorId));
  ok("actor row counts sum across both emails", a[0].actions === 7, a[0]);
  ok("newest email wins as the display name", a[0].actorEmail === ACTOR_A.email, a[0].actorEmail);
  ok("lastAt is the newest row for that actor", a[0].lastAt.getTime() === at(16).getTime(), a[0].lastAt);
  ok("actor list grew by two", actors.length === beforeActors.length + 2, {
    before: beforeActors.length,
    now: actors.length,
  });

  // ── 9. Vocabulary metadata the page renders ────────────────────────────
  ok("isAdminAction accepts a real name", A.isAdminAction("user.viewed"));
  ok("isAdminAction rejects a prototype key", !A.isAdminAction("toString") && !A.isAdminAction("constructor"));
  ok("describeAdminAction on an unknown name is null", A.describeAdminAction("legacy.thing") === null);
  const d = A.describeAdminAction("site.taken_down");
  ok("descriptor carries label/kind/surface", d.label.length > 0 && d.kind === "write" && d.surface === "sites", d);
  const groups = A.adminActionsBySurface();
  const flat = groups.flatMap((g) => g.actions.map((x) => x.action));
  ok(
    "every action appears in exactly one surface group",
    flat.length === Object.keys(A.ADMIN_ACTION_INFO).length && new Set(flat).size === flat.length,
    { grouped: flat.length, vocabulary: Object.keys(A.ADMIN_ACTION_INFO).length },
  );
  ok("no empty groups", groups.every((g) => g.actions.length > 0 && g.label.length > 0));
  const pending = A.pendingAdminActions();
  ok(
    "pending excludes the two emitters",
    !pending.some((p) => p.action === "site.taken_down" || p.action === "audit_log.viewed"),
    pending.map((p) => p.action),
  );
  const firstRead = pending.findIndex((p) => p.kind === "read");
  const lastWrite = pending.map((p) => p.kind).lastIndexOf("write");
  ok("pending lists writes before reads", lastWrite < firstRead, { firstRead, lastWrite });

  // Every real row in the table (ours and other agents') is a name the page
  // can render — i.e. nothing has written outside the vocabulary.
  const distinct = await db.adminAuditLog.groupBy({ by: ["action"] });
  const unknown = distinct.map((r) => r.action).filter((x) => !A.isAdminAction(x));
  ok("no row in the table is outside the vocabulary", unknown.length === 0, unknown);

  // ── Cleanup ────────────────────────────────────────────────────────────
  const removed = await db.adminAuditLog.deleteMany({ where: { actorId: { startsWith: PREFIX } } });
  ok("cleanup removed exactly the rows we wrote", removed.count === mine, removed);
  ok("row count is back to where it started", (await db.adminAuditLog.count()) === beforeTotal);

  console.log(failures === 0 ? "\nALL PASS" : `\n${failures} FAILURE(S)`);
  await db.$disconnect();
  process.exit(failures === 0 ? 0 : 1);
}

main().catch(async (e) => {
  console.error("THREW:", e);
  try {
    const r = await db.adminAuditLog.deleteMany({ where: { actorId: { startsWith: PREFIX } } });
    console.error("cleanup removed", r.count);
  } catch {}
  await db.$disconnect();
  process.exit(1);
});

